private Integer parseISupportAwayLen(final IIRCState state) {
  final Map<String, String> options = state.getServerOptions();
  if (options == null) {
    return null;
  }
  final String value = options.getKey(ISupport.AWAYLEN.name());
  if (value == null) {
    return null;
  }
  if (LOGGER.isDebugEnabled()) {
    LOGGER.debug("Setting ISUPPORT parameter " + ISupport.AWAYLEN.name() + " to " + value);
  }
  try {
    return new Integer(value);
  } catch (NumberFormatException e) {
    LOGGER.warn("Invalid ISUPPORT away length: " + value, e);
    return null;
  }
}
